from fastapi import FastAPI
from pydantic import BaseModel
import uvicorn

app = FastAPI(title='PyC45 Model API', version='1.0')

class ClientData(BaseModel):
    LIMIT_BAL: float
    SEX: float
    EDUCATION: float
    MARRIAGE: float
    AGE: float
    PAY_0: float
    PAY_2: float
    PAY_3: float
    PAY_4: float
    PAY_5: float
    PAY_6: float
    BILL_AMT1: float
    BILL_AMT2: float
    BILL_AMT3: float
    BILL_AMT4: float
    BILL_AMT5: float
    BILL_AMT6: float
    PAY_AMT1: float
    PAY_AMT2: float
    PAY_AMT3: float
    PAY_AMT4: float
    PAY_AMT5: float
    PAY_AMT6: float

def predict_c45(client):
    """
    Predicción generada automáticamente por PyC45.
    client: diccionario con los valores de las variables.
    """
    if client.get('PAY_0', 0.0) <= 1.5000:
        if client.get('PAY_6', 0.0) <= 7.0000:
            if client.get('BILL_AMT6', 0.0) <= -274327.0000:
                return 1  # Hoja (n=1, prob=100.00%)
            else:
                if client.get('PAY_2', 0.0) <= 2.5000:
                    return 0  # Hoja (n=18713, prob=83.89%)
                else:
                    return 1  # Hoja (n=147, prob=53.74%)
        else:
            return 1  # Hoja (n=1, prob=100.00%)
    else:
        if client.get('BILL_AMT1', 0.0) <= 101.0000:
            return 0  # Hoja (n=4, prob=100.00%)
        else:
            if client.get('BILL_AMT2', 0.0) <= -1150.5000:
                return 0  # Hoja (n=2, prob=100.00%)
            else:
                if client.get('EDUCATION', 0.0) <= 5.5000:
                    return 1  # Hoja (n=2131, prob=70.48%)
                else:
                    return 0  # Hoja (n=1, prob=100.00%)

@app.post('/predict')
def predict(data: ClientData):
    client_dict = data.dict()
    pred = predict_c45(client_dict)
    return {'prediction': pred}

if __name__ == '__main__':
    uvicorn.run(app, host='0.0.0.0', port=8000)
